#include <stdio.h>
#include <stdlib.h>

#define MAX_SIZE 1024

typedef struct ListNode {
    int ele;
    struct ListNode *next;
} ListNode;

typedef struct {
    int size;
    ListNode *head;
    ListNode *tail;
} LinkedList;

LinkedList *new_LinkedList();
void addLast_LinkedList(LinkedList *link, int ele);

int matrix[MAX_SIZE][MAX_SIZE] = {0};

int main() {
    int m, n, i, j, k, l;
    scanf("%d,%d,%d,%d,%d,%d", &m, &n, &i, &j, &k, &l);

    // 初始扩散点位置为i,j
    matrix[i][j] = 1;
    // 初始扩散点位置为k,l
    matrix[k][l] = 1;

    // count记录未被扩散的点的数量
    int count = m * n - 2;

    // 多源BFS实现队列
    LinkedList *queue = new_LinkedList();
    addLast_LinkedList(queue, i * n + j);
    addLast_LinkedList(queue, k * n + l);

    // 上下左右偏移量
    int offsets[4][2] = {{1,  0},
                         {-1, 0},
                         {0,  1},
                         {0,  -1}};

    // 扩散时间
    int day = 0;

    // 如果扩散点没有了，或者所有点已被扩散，则停止循环
    while (queue->size > 0 && count > 0) {
        LinkedList *newQueue = new_LinkedList();

        ListNode *cur = queue->head;
        while (cur != NULL) {
            int x = cur->ele / n;
            int y = cur->ele % n;

            for (int a = 0; a < 4; a++) {
                int newX = x + offsets[a][0];
                int newY = y + offsets[a][1];

                if (newX >= 0 && newX < m && newY >= 0 && newY < n && matrix[newX][newY] == 0) {
                    // 将点被扩散的时间记录为该点的值
                    matrix[newX][newY] = 1;
                    // 被扩散到的点将变为新的扩散源
                    addLast_LinkedList(newQueue, newX * n + newY);
                    // 未被扩散点的数量--
                    count--;
                }
            }
            cur = cur->next;
        }

        queue = newQueue;
        day++;
    }

    printf("%d\n", day);

    return 0;
}

LinkedList *new_LinkedList() {
    LinkedList *link = (LinkedList *) malloc(sizeof(LinkedList));

    link->size = 0;
    link->head = NULL;
    link->tail = NULL;

    return link;
}

void addLast_LinkedList(LinkedList *link, int ele) {
    ListNode *node = (ListNode *) malloc(sizeof(ListNode));

    node->ele = ele;
    node->next = NULL;

    if (link->size == 0) {
        link->head = node;
        link->tail = node;
    } else {
        link->tail->next = node;
        link->tail = node;
    }

    link->size++;
}
